actions.script:
const out = ec.service.sync().name('org.moqui.call.CallHandlingServices.search#Dialable').parameters({text: text || '', limit: 10})
    .requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse({resultList: out.resultList || [], number: out.number || null, failedCount: Array.from(out.failedParts || []).length})
